/* Olympiad mathematics: ten independent techniques, five parameter sets. */
(()=>{
const add=(grade,index,title,question,answer,hints,steps)=>tasks.push({id:`olympiad-fifty-${grade}-${index}`,domain:'math',grade,topic:0,subject:topicSubjects[`${grade}-0`],topicName:curriculum[grade][0][0],level:3,title,question,answer,hints,steps,goal:'Найти идею и доказать ответ',challenge:true,review:{plan:hints[0],verify:steps[steps.length-1],trap:'Проверь, что доказана и граница, и её достижимость, когда это требуется.'}});
const choose=(n,k)=>{let v=1;for(let j=1;j<=k;j++)v=v*(n-j+1)/j;return Math.round(v)};
const gcd=(a,b)=>b?gcd(b,a%b):a;
for(let grade=7;grade<=11;grade++){
 const t=grade-7,n=5+t;
 // Wilson and a multiplicative invariant.
 const primes=[11,13,17,19,23],p=primes[t];
 add(grade,1,'Факториал под маской инварианта',`На доске записаны числа 1, 2, …, ${p-2}. За ход два числа a и b заменяют числом a+b+ab. Какой остаток при делении на ${p} может иметь последнее число? Докажи независимость от порядка ходов.`,p-2,
 ['Прибавь единицу к результату хода.','Используй обратные элементы по простому модулю.'],
 [`При замене a и b величина (a+1)(b+1) переходит в (a+b+ab)+1, поэтому произведение всех чисел, увеличенных на единицу, сохраняется.`,`В конце N+1 равно 2·3·…·${p-1} = (${p-1})!.`,`Число ${p} простое. Все ненулевые остатки, кроме 1 и −1, разбиваются на пары взаимно обратных; поэтому (${p-1})! ≡ −1 (mod ${p}).`,`Следовательно N ≡ −2 ≡ ${p-2} (mod ${p}); любой порядок ходов даёт этот остаток.`]);
 // Sperner, proof via permutations.
 const m=4+2*t,k=m/2,ans=choose(m,k);
 add(grade,2,'Семейство без вложений',`Выбрано несколько различных подмножеств множества из ${m} элементов. Ни одно выбранное множество не содержится в другом. Каково наибольшее возможное число выбранных множеств?`,ans,
 ['Рассмотри все перестановки и их начальные отрезки.','Подсчитай пары «перестановка — выбранное множество».'],
 [`Множество A мощности j является множеством первых j элементов ровно в j!(${m}−j)! перестановках.`,`В одной перестановке начальные отрезки образуют цепь по включению, поэтому не более одного из них может быть выбранным. Деление на ${m}! даёт Σ 1/C(${m}, |A|) ≤ 1.`,`Все биномиальные коэффициенты C(${m},j) не больше C(${m},${k}) = ${ans}; каждый член суммы не меньше 1/${ans}. Поэтому число выбранных множеств не превосходит ${ans}.`,`Все ${ans} подмножеств мощности ${k} попарно не содержат друг друга. Граница достигается.`]);
 // Extremal graph Mantel.
 const v=9+2*t,max=Math.floor(v*v/4),a=Math.floor(v/2),b=v-a;
 add(grade,3,'Дружбы без треугольника',`На встрече ${v} человек; некоторые пары знакомы взаимно. Никакие трое не знакомы попарно. Какое максимальное число пар знакомств возможно?`,max,
 ['Для любого ребра сравни множества соседей его концов.','Просуммируй неравенство по рёбрам и примени Коши.'],
 [`Пусть степени вершин d₁,…,d_${v}, а рёбер E. Для каждого ребра uv общих соседей нет, значит d(u)+d(v) ≤ ${v}.`,`Сумма этих величин по рёбрам равна Σdᵢ², следовательно Σdᵢ² ≤ ${v}E. По Коши Σdᵢ² ≥ (2E)²/${v}.`,`При E>0 отсюда E ≤ ${v}²/4, то есть E ≤ ${max}. Для E=0 граница очевидна.`,`Разделим людей на группы по ${a} и ${b} человек и соединим все пары из разных групп. Получим ${a}·${b} = ${max} знакомств без треугольника.`]);
 // Vieta descent Markov-type equation.
 const thresholds=[30,100,300,1000,2500],limit=thresholds[t];let x=1,y=1;while(x+y<=limit){[x,y]=[y,3*y-x]};
 add(grade,4,'Спуск по Виету',`Положительные целые x и y удовлетворяют x²+y²+1=3xy. Найди наименьшую сумму x+y, строго превосходящую ${limit}. Докажи, что других решений с меньшей подходящей суммой нет.`,x+y,
 ['Зафиксируй x и замени корень квадратного уравнения на второй.','Докажи уменьшение и установи начальную пару.'],
 [`Упорядочим x≤y. Второй корень по Виету равен y′=3x−y=(x²+1)/y, значит он целый и положительный.`,`При x>1 для f(z)=z²−3xz+x²+1 выполнено f(0)>0 и f(x)=1−x²<0. Значит меньший корень y′ лежит между 0 и x, а y>x. Замена (x,y)→(y′,x) уменьшает максимум.`,`Спуск заканчивается при x=1, когда y=1 или 2. Обратная операция (a,b)→(b,3b−a) порождает все упорядоченные решения; начиная с (1,1), суммы строго возрастают.`,`Последовательное построение даёт соседние с порогом суммы ${(()=>{let a=1,b=1,prev=2;while(a+b<=limit){prev=a+b;[a,b]=[b,3*b-a]}return prev})()} и ${x+y}. Следовательно искомая сумма ${x+y}.`]);
 // Binomial parity via binary expansion.
 const ns=[2023,2024,2025,2026,2027],q=ns[t],ones=q.toString(2).split('1').length-1,odd=2**ones;
 add(grade,5,'Нечётные коэффициенты',`Сколько нечётных чисел среди C(${q},0), C(${q},1), …, C(${q},${q})? Ответ обоснуй без вычисления всех коэффициентов.`,odd,
 ['Работай с (1+x)^N по модулю 2.','Разложи показатель в сумму различных степеней двойки.'],
 [`В арифметике по модулю 2 верно (1+x)²≡1+x². Повторяя возведение в квадрат, получаем (1+x)^(2^j)≡1+x^(2^j).`,`Двоичная запись числа ${q} содержит ${ones} единиц: ${q.toString(2)}₂. Поэтому (1+x)^${q} сравним с произведением ${ones} множителей вида (1+x^(2^j)).`,`В каждом множителе можно независимо выбрать 1 или x^(2^j). По единственности двоичной записи все полученные степени различны и имеют коэффициент 1 по модулю 2.`,`Нечётных коэффициентов ровно 2^${ones} = ${odd}.`]);
 // Erdős–Szekeres.
 const r=3+t,seq=(r-1)**2+1,avoid=(r-1)**2;
 add(grade,6,'Монотонная подпоследовательность',`Каково наименьшее N, при котором в любой последовательности из N попарно различных чисел обязательно найдётся возрастающая или убывающая подпоследовательность длины ${r}?`,seq,
 ['Каждому числу сопоставь длины лучших возрастающей и убывающей подпоследовательностей, заканчивающихся им.','Построй обратный пример из убывающих блоков.'],
 [`Для каждого элемента отметим пару (a,b): максимальные длины возрастающей и убывающей подпоследовательностей, заканчивающихся этим элементом.`,`Если i<j и aᵢ=aⱼ, bᵢ=bⱼ, то при xᵢ<xⱼ можно продолжить возрастающую подпоследовательность, а при xᵢ>xⱼ — убывающую. Оба случая противоречат равенству пар.`,`Если подпоследовательности длины ${r} нет, каждая координата пары не больше ${r-1}. Различных пар не более ${avoid}, так что N=${seq} достаточно.`,`Граница точна: возьмём ${r-1} убывающих блоков по ${r-1} чисел, при этом все числа каждого следующего блока больше всех чисел предыдущего. Монотонная подпоследовательность любого направления имеет длину не больше ${r-1}.`]);
 // lattice path reflection.
 const side=5+t,total=choose(2*side,side),cat=total/(side+1);
 add(grade,7,'Путь, не пересекающий диагональ',`На клетчатой плоскости из (0;0) в (${side};${side}) идут только вправо и вверх по рёбрам клеток. Сколько путей никогда не поднимаются выше прямой y=x?`,cat,
 ['Вычти из числа всех путей те, которые впервые нарушают условие.','Отрази начальный участок до первого попадания на y=x+1.'],
 [`Всего путей C(${2*side},${side}) = ${total}.`,`У каждого плохого пути есть первый шаг, после которого y=x+1. Отразим относительно диагонали весь участок до этой точки, поменяв шаги вверх и вправо.`,`Получается взаимно однозначное соответствие между плохими путями и путями от (0;0) до (${side+1};${side-1}); их C(${2*side},${side-1}). Обратное отражение выполняется до первого попадания на x=y+1.`,`Поэтому подходящих путей C(${2*side},${side})−C(${2*side},${side-1})=C(${2*side},${side})/${side+1}=${cat}.`]);
 // Inversion parity through binary code.
 const power=4+t,N=2**power;
 add(grade,8,'Нечётность биномиальных коэффициентов',`Сколько упорядоченных пар целых чисел (i,j), где 0≤i,j<${N}, обладают свойством: биномиальный коэффициент C(i+j,i) нечётен?`,3**power,
 ['Найди показатель двойки в факториале через сумму двоичных цифр.','Установи связь с переносами при сложении i и j.'],
 [`По формуле Лежандра v₂(n!)=⌊n/2⌋+⌊n/4⌋+…=n−s₂(n), где s₂(n) — сумма двоичных цифр n.`,`Следовательно v₂(C(i+j,i))=s₂(i)+s₂(j)−s₂(i+j). При каждом переносе единицы в следующий разряд сумма цифр уменьшается на 1, поэтому показатель равен числу переносов.`,`Коэффициент нечётен тогда и только тогда, когда переносов нет. В каждом из ${power} разрядов разрешены пары цифр (0,0), (0,1), (1,0); пара (1,1) создаёт перенос.`,`Разряды выбираются независимо. Искомое число упорядоченных пар равно 3^${power}=${3**power}.`]);
 // Sum of gcds: Euclid plus divisor grouping.
 const aa=[12,18,24,30,36][t],ga=Array.from({length:aa},(_,i)=>2**gcd(aa,i+1)-1).reduce((a,b)=>a+b,0);
 add(grade,9,'Сумма НОД огромных чисел',`Найди точное значение суммы НОД(2^${aa}−1,2^k−1) по всем целым k от 1 до ${aa} включительно.`,ga,
 ['Сначала докажи формулу НОД для чисел вида 2^n−1.','Сгруппируй показатели k по значению НОД(${aa},k).'],
 [`При a≥b разность (2^a−1)−2^(a−b)(2^b−1) равна 2^(a−b)−1. Алгоритм Евклида для показателей даёт НОД(2^a−1,2^b−1)=2^НОД(a,b)−1.`,`Следовательно исходная сумма равна Σₖ₌₁^${aa}(2^НОД(${aa},k)−1).`,`Если d — делитель ${aa}, условие НОД(${aa},k)=d равносильно k=d·j, где 1≤j≤${aa}/d и НОД(j,${aa}/d)=1. Таких j ровно φ(${aa}/d).`,`Сумма равна Σ_{d|${aa}} φ(${aa}/d)(2^d−1) = ${ga}. Для каждого делителя φ можно вычислить как m·∏(1−1/p) по различным простым делителям m.`]);
 // Inclusion–exclusion for forbidden fixed points.
 const size=6+t;let previous=1,current=0;for(let j=2;j<=size;j++){const next=(j-1)*(current+previous);previous=current;current=next}const derangements=current;
 add(grade,10,'Перестановки без неподвижных точек',`Сколькими способами можно рассадить ${size} человек на ${size} пронумерованных мест так, чтобы никто не сел на место со своим номером? Выведи ответ, обосновав подсчёт.`,derangements,
 ['Применяй принцип включений и исключений к событиям «человек i сел на место i».','Можно получить тот же ответ рекуррентно, разделив случаи по месту человека, севшего на первое место.'],
 [`Всего имеется ${size}! перестановок. Если зафиксированы места заранее выбранных k человек, остальных можно рассадить (${size}−k)! способами; таких k-элементных наборов C(${size},k).`,`По принципу включений и исключений искомое число равно Σₖ₌₀^${size} (−1)^k C(${size},k)(${size}−k)! = ${size}!·Σₖ₌₀^${size}(−1)^k/k!.`,`Проверим результат рекурсией D₀=1, D₁=0, Dₙ=(n−1)(Dₙ₋₁+Dₙ₋₂). Выберем место j≠1 для первого человека. Если человек j сел на место 1, оставшиеся дают Dₙ₋₂; иначе, после объединения связанных мест, получается Dₙ₋₁.`,`Для n=${size} вычисление даёт D_${size}=${derangements}.`]);

}
})();
